func writeAttributeValue(w hugio.FlexiWriter, v any) {
	switch vv := v.(type) {
	case []byte:
		_, _ = w.Write(util.EscapeHTML(vv))
	case string:
		_, _ = w.Write(util.EscapeHTML([]byte(vv)))
	default:
		_, _ = w.Write(util.EscapeHTML([]byte(cast.ToString(vv))))
	}
}

